def compute_order_amount(on_hand_inventory, pipeline_orders):
    base_stock = 334.3043852374433  # OPT_PARAM: {"initial": 334.3043852374433, "min": 200, "max": 500, "type": "float"}
    order_cap = 62.13534027821758  # OPT_PARAM: {"initial": 62.13534027821758, "min": 50, "max": 300, "type": "float"}
    safety_stock = 10.111504122043028  # OPT_PARAM: {"initial": 10.111504122043028, "min": 10, "max": 60, "type": "float"}
    demand_buffer = 1.3624215032940683  # OPT_PARAM: {"initial": 1.3624215032940683, "min": 0.8, "max": 1.8, "type": "float"}
    pipeline_weight = 0.3853283076560305  # OPT_PARAM: {"initial": 0.3853283076560305, "min": 0.3, "max": 1.0, "type": "float"}
    recent_periods = 3  # OPT_PARAM: {"initial": 3, "min": 1, "max": 8, "type": "int"}
    min_order = 43.80154980093803  # OPT_PARAM: {"initial": 43.80154980093803, "min": 0, "max": 50, "type": "float"}
    demand_smoothing = 0.8077417042138141  # OPT_PARAM: {"initial": 0.8077417042138141, "min": 0.1, "max": 1.0, "type": "float"}

    # Calculate inventory position
    inventory_position = on_hand_inventory + sum(pipeline_orders)

    # Calculate weighted pipeline coverage
    weighted_pipeline = sum(p * (pipeline_weight ** i) for i, p in enumerate(pipeline_orders))

    # Estimate demand from recent pipeline orders with smoothing
    recent_orders = pipeline_orders[-recent_periods:] if len(pipeline_orders) >= recent_periods else pipeline_orders
    if recent_orders:
        avg_recent_demand = sum(recent_orders) / len(recent_orders)
        # Apply smoothing to reduce volatility
        smoothed_demand = avg_recent_demand * demand_smoothing + base_stock * (1 - demand_smoothing) / 10
    else:
        smoothed_demand = 0

    # Adjust base stock based on smoothed demand
    adjusted_base_stock = base_stock + (smoothed_demand * demand_buffer) - weighted_pipeline

    # Calculate order quantity with stronger safety stock
    target_order = adjusted_base_stock - inventory_position + safety_stock * 1.5
    target_order = max(min_order, target_order)

    # Apply order cap
    order_amount = min(target_order, order_cap)

    return order_amount
